10|int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
11|  struct __attribute__((packed)) {
12|    int options;
13|    int width;
14|  } fuzz_config;
15|
16|  if (size >= sizeof(fuzz_config)) {
17|    /* The beginning of `data` is treated as fuzzer configuration */
18|    memcpy(&fuzz_config, data, sizeof(fuzz_config));
19|    int options = fuzz_config.options;
20|
21|    /* Mask off valid option bits */
22|    options &= (CMARK_OPT_SOURCEPOS | CMARK_OPT_HARDBREAKS | CMARK_OPT_UNSAFE | CMARK_OPT_NOBREAKS | CMARK_OPT_NORMALIZE | CMARK_OPT_VALIDATE_UTF8 | CMARK_OPT_SMART);
23|
24|    /* Remainder of input is the markdown */
25|    const char *markdown = (const char *)(data + sizeof(fuzz_config));
26|    size_t markdown_size = size - sizeof(fuzz_config);
27|    cmark_node *doc = NULL;
28|
29|    /* Use upper bits of options to select parsing mode */
30|    switch (((unsigned) fuzz_config.options >> 30) & 3) {
31|      case 0:
32|        doc = cmark_parse_document(markdown, markdown_size, options);
33|        break;
34|
35|      case 1:
36|        if (markdown_size > 0) {
37|          FILE *file = fmemopen((void *) markdown, markdown_size, "r");
38|          doc = cmark_parse_file(file, options);
39|          fclose(file);
40|        }
41|        break;
42|
43|      case 2: {
44|        size_t block_max = 20;
45|        cmark_parser *parser = cmark_parser_new(options);
46|
47|        while (markdown_size > 0) {
48|          size_t block_size = markdown_size > block_max ? block_max : markdown_size;
49|          cmark_parser_feed(parser, markdown, block_size);
50|          markdown += block_size;
51|          markdown_size -= block_size;
52|        }
53|
54|        doc = cmark_parser_finish(parser);
55|        cmark_parser_free(parser);
56|        break;
57|      }
58|
59|      case 3:
60|        free(cmark_markdown_to_html(markdown, markdown_size, options));
61|        break;
62|    }
63|
64|    if (doc != NULL) {
65|      free(cmark_render_commonmark(doc, options, fuzz_config.width));
66|      free(cmark_render_html(doc, options));
67|      free(cmark_render_latex(doc, options, fuzz_config.width));
68|      free(cmark_render_man(doc, options, fuzz_config.width));
69|      free(cmark_render_xml(doc, options));
70|
71|      cmark_node_free(doc);
72|    }
73|  }
74|  return 0;
75|}

220|static int S_render_node(cmark_renderer *renderer, cmark_node *node,
221|                         cmark_event_type ev_type, int options) {
222|  int list_number;
223|  int enumlevel;
224|  char list_number_string[LIST_NUMBER_STRING_SIZE];
225|  bool entering = (ev_type == CMARK_EVENT_ENTER);
226|  cmark_list_type list_type;
227|  bool allow_wrap = renderer->width > 0 && !(CMARK_OPT_NOBREAKS & options);
228|
229|  // avoid warning about unused parameter:
230|  (void)(options);
231|
232|  switch (node->type) {
233|  case CMARK_NODE_DOCUMENT:
234|    break;
235|
236|  case CMARK_NODE_BLOCK_QUOTE:
237|    if (entering) {
238|      LIT("\\begin{quote}");
239|      CR();
240|    } else {
241|      LIT("\\end{quote}");
242|      BLANKLINE();
243|    }
244|    break;
245|
246|  case CMARK_NODE_LIST:
247|    list_type = cmark_node_get_list_type(node);
248|    if (entering) {
249|      LIT("\\begin{");
250|      LIT(list_type == CMARK_ORDERED_LIST ? "enumerate" : "itemize");
251|      LIT("}");
252|      CR();
253|      list_number = cmark_node_get_list_start(node);
254|      if (list_number > 1) {
255|        enumlevel = S_get_enumlevel(node);
256|        // latex normally supports only five levels
257|        if (enumlevel >= 1 && enumlevel <= 5) {
258|          snprintf(list_number_string, LIST_NUMBER_STRING_SIZE, "%d",
259|                   list_number - 1); // the next item will increment this
260|          LIT("\\setcounter{enum");
261|          switch (enumlevel) {
262|          case 1: LIT("i"); break;
263|          case 2: LIT("ii"); break;
264|          case 3: LIT("iii"); break;
265|          case 4: LIT("iv"); break;
266|          case 5: LIT("v"); break;
267|          default: LIT("i"); break;
268|          }
269|          LIT("}{");
270|          OUT(list_number_string, false, NORMAL);
271|          LIT("}");
272|        }
273|        CR();
274|      }
275|    } else {
276|      LIT("\\end{");
277|      LIT(list_type == CMARK_ORDERED_LIST ? "enumerate" : "itemize");
278|      LIT("}");
279|      BLANKLINE();
280|    }
281|    break;
282|
283|  case CMARK_NODE_ITEM:
284|    if (entering) {
285|      LIT("\\item ");
286|    } else {
287|      CR();
288|    }
289|    break;
290|
291|  case CMARK_NODE_HEADING:
292|    if (entering) {
293|      switch (cmark_node_get_heading_level(node)) {
294|      case 1:
295|        LIT("\\section");
296|        break;
297|      case 2:
298|        LIT("\\subsection");
299|        break;
300|      case 3:
301|        LIT("\\subsubsection");
302|        break;
303|      case 4:
304|        LIT("\\paragraph");
305|        break;
306|      case 5:
307|        LIT("\\subparagraph");
308|        break;
309|      }
310|      LIT("{");
311|    } else {
312|      LIT("}");
313|      BLANKLINE();
314|    }
315|    break;
316|
317|  case CMARK_NODE_CODE_BLOCK:
318|    CR();
319|    LIT("\\begin{verbatim}");
320|    CR();
321|    OUT(cmark_node_get_literal(node), false, LITERAL);
322|    CR();
323|    LIT("\\end{verbatim}");
324|    BLANKLINE();
325|    break;
326|
327|  case CMARK_NODE_HTML_BLOCK:
328|    break;
329|
330|  case CMARK_NODE_CUSTOM_BLOCK:
331|    CR();
332|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
333|        false, LITERAL);
334|    CR();
335|    break;
336|
337|  case CMARK_NODE_THEMATIC_BREAK:
338|    BLANKLINE();
339|    LIT("\\begin{center}\\rule{0.5\\linewidth}{\\linethickness}\\end{center}");
340|    BLANKLINE();
341|    break;
342|
343|  case CMARK_NODE_PARAGRAPH:
344|    if (!entering) {
345|      BLANKLINE();
346|    }
347|    break;
348|
349|  case CMARK_NODE_TEXT:
350|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
351|    break;
352|
353|  case CMARK_NODE_LINEBREAK:
354|    LIT("\\\\");
355|    CR();
356|    break;
357|
358|  case CMARK_NODE_SOFTBREAK:
359|    if (options & CMARK_OPT_HARDBREAKS) {
360|      LIT("\\\\");
361|      CR();
362|    } else if (renderer->width == 0 && !(CMARK_OPT_NOBREAKS & options)) {
363|      CR();
364|    } else {
365|      OUT(" ", allow_wrap, NORMAL);
366|    }
367|    break;
368|
369|  case CMARK_NODE_CODE:
370|    LIT("\\texttt{");
371|    OUT(cmark_node_get_literal(node), false, NORMAL);
372|    LIT("}");
373|    break;
374|
375|  case CMARK_NODE_HTML_INLINE:
376|    break;
377|
378|  case CMARK_NODE_CUSTOM_INLINE:
379|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
380|        false, LITERAL);
381|    break;
382|
383|  case CMARK_NODE_STRONG:
384|    if (entering) {
385|      LIT("\\textbf{");
386|    } else {
387|      LIT("}");
388|    }
389|    break;
390|
391|  case CMARK_NODE_EMPH:
392|    if (entering) {
393|      LIT("\\emph{");
394|    } else {
395|      LIT("}");
396|    }
397|    break;
398|
399|  case CMARK_NODE_LINK:
400|    if (entering) {
401|      const char *url = cmark_node_get_url(node);
402|      // requires \usepackage{hyperref}
403|      switch (get_link_type(node)) {
404|      case URL_AUTOLINK:
405|        LIT("\\url{");
406|        OUT(url, false, URL);
407|        LIT("}");
408|        return 0; // Don't process further nodes to avoid double-rendering artefacts
409|      case EMAIL_AUTOLINK:
410|        LIT("\\href{");
411|        OUT(url, false, URL);
412|        LIT("}\\nolinkurl{");
413|        break;
414|      case NORMAL_LINK:
415|        LIT("\\href{");
416|        OUT(url, false, URL);
417|        LIT("}{");
418|        break;
419|      case INTERNAL_LINK:
420|        LIT("\\protect\\hyperlink{");
421|        OUT(url + 1, false, URL);
422|        LIT("}{");
423|        break;
424|      case NO_LINK:
425|        LIT("{"); // error?
426|      }
427|    } else {
428|      LIT("}");
429|    }
430|
431|    break;
432|
433|  case CMARK_NODE_IMAGE:
434|    if (entering) {
435|      LIT("\\protect\\includegraphics{");
436|      // requires \include{graphicx}
437|      OUT(cmark_node_get_url(node), false, URL);
438|      LIT("}");
439|      return 0;
440|    }
441|    break;
442|
443|  default:
444|    assert(false);
445|    break;
446|  }
447|
448|  return 1;
449|}

